# EventBridge rule fanning agent-completion events to a Step Functions state machine
resource "aws_cloudwatch_event_rule" "agent_session_complete" {
  name           = "bedrock-agent-session-complete"
  event_bus_name = aws_cloudwatch_event_bus.ai_platform.name
  event_pattern  = jsonencode({
    source      = ["custom.bedrock-agent"]
    detail-type = ["AgentSessionCompleted"]
  })
}

resource "aws_cloudwatch_event_target" "start_followup_workflow" {
  rule           = aws_cloudwatch_event_rule.agent_session_complete.name
  event_bus_name = aws_cloudwatch_event_bus.ai_platform.name
  arn            = aws_sfn_state_machine.claims_followup.arn
  role_arn       = aws_iam_role.eventbridge_invoke_sfn.arn

  dead_letter_config {
    arn = aws_sqs_queue.agent_events_dlq.arn
  }
}
